#!/usr/bin/env node
/**
 * Embeds the backend's parametric jewelry geometry (backend/src/jewelry/geometry.ts) in the app's
 * 3D studio, so the preview, the STL export and the rendered pictures are built by the same code.
 *
 *   node scripts/sync-jewelry-geometry.cjs          writes src/lib/jewelryGeometry.generated.ts
 *   node scripts/sync-jewelry-geometry.cjs --check  exits 1 when the generated file is stale
 *
 * The geometry is transpiled to ES2017 and wrapped so it defines `window.JewelryGeometry` inside
 * the viewer's WebView.
 */
const { createHash } = require('crypto')
const { existsSync, readFileSync, writeFileSync } = require('fs')
const { join } = require('path')
const ts = require('typescript')

const APP = join(__dirname, '..')
const SOURCE = join(APP, '..', 'backend', 'src', 'jewelry', 'geometry.ts')
const TARGET = join(APP, 'src', 'lib', 'jewelryGeometry.generated.ts')

function generate(source) {
  const sha = createHash('sha256').update(source).digest('hex')
  const js = ts.transpileModule(source, {
    compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2017, removeComments: true },
  }).outputText
  const wrapped = `(function () {\nvar exports = {};\n${js}\nwindow.JewelryGeometry = exports;\n})();\n`
  return [
    '/* eslint-disable */',
    '// Generated by scripts/sync-jewelry-geometry.cjs from backend/src/jewelry/geometry.ts — do not edit.',
    '// Run `node scripts/sync-jewelry-geometry.cjs` after changing the backend geometry.',
    '',
    `export const JEWELRY_GEOMETRY_SOURCE_SHA256 = '${sha}'`,
    '',
    `export const JEWELRY_GEOMETRY_JS = ${JSON.stringify(wrapped)}`,
    '',
  ].join('\n')
}

if (!existsSync(SOURCE)) {
  console.error(`Backend geometry not found at ${SOURCE}`)
  process.exit(1)
}
// Line endings do not count: a Windows checkout may turn them into CRLF.
const lf = (text) => text.replace(/\r\n/g, '\n')
const output = generate(lf(readFileSync(SOURCE, 'utf8')))
if (process.argv.includes('--check')) {
  const current = existsSync(TARGET) ? lf(readFileSync(TARGET, 'utf8')) : ''
  if (current !== output) {
    console.error('src/lib/jewelryGeometry.generated.ts is stale: run node scripts/sync-jewelry-geometry.cjs')
    process.exit(1)
  }
  console.log('jewelry geometry is in sync')
} else {
  writeFileSync(TARGET, output)
  console.log(`wrote ${TARGET}`)
}
